Query: given a list of transaction objects that contain coin name,datetime,profit earned/loss. write a function in dart that returns the top three coins with the highest average profit and the top 3 coins with highest average loss.

Response A: 

[SOLUTION]

Here's a Dart function that returns the top three coins with the highest average profit and the top 3 coins with highest average loss:
```dart
import 'dart:collection';

List<Transaction> calculateTopCoins(List<Transaction> transactions) {
  List<Transaction> topProfitCoins = [];
  List<Transaction> topLossCoins = [];

  Map<String, Transaction> coinProfitMap = {};
  Map<String, Transaction> coinLossMap = {};

  for (Transaction transaction in transactions) {
    String coinName = transaction.coinName;
    double profit = transaction.profitEarned;
    double loss = transaction.profitLoss;

    if (coinProfitMap.containsKey(coinName)) {
      coinProfitMap[coinName] = coinProfitMap[coinName] + profit;
    } else {
      coinProfitMap[coinName] = profit;
    }

    if (coinLossMap.containsKey(coinName)) {
      coinLossMap[coinName] = coinLossMap[coinName] + loss;
    } else {
      coinLossMap[coinName] = loss;
    }
  }

  List<String> sortedProfitCoins = coinProfitMap.entries.toList()
    .where((entry) => entry.value > 0)
    .map((entry) => entry.key)
    .toList();

  List<String> sortedLossCoins = coinLossMap.entries.toList()
    .where((entry) => entry.value < 0)
    .map((entry) => entry.key)
    .toList();

  for (int i = 0; i < 3; i++) {
    topProfitCoins.add(transactions.firstWhere((coin) => coin.coinName == sortedProfitCoins[i], orElse: () => Transaction()));
    topLossCoins.add(transactions.firstWhere((coin) => coin.coinName == sortedLossCoins[i], orElse: () => Transaction()));
  }

  return [topProfitCoins, topLossCoins];
}
```
