  Transaction(coinName: "Bitcoin", datetime: DateTime.now(), profitLoss: 2.0),
  Transaction(coinName: "Ethereum", datetime: DateTime.now(), profitLoss: 1.0),
];

List<List<Transaction>> topCoins = calculateTopCoins(transactions);

print("Top 3 Coins with Highest Average Profit:");
for (List<Transaction> coins in topCoins[0]) {
  print(coins.first.coinName);
}

print("\nTop 3 Coins with Highest Average Loss:");
for (List<Transaction> coins in topCoins[1]) {
