  Transaction(coinName: 'Litecoin', datetime: DateTime(2022, 1, 6), profit: -70),
];

List<Transaction> sortTransactions(List<Transaction> transactions, bool ascending) {
  return transactions.sort((a, b) => a.profit.compareTo(b.profit) * ascending);
}

List<String> getTopCoins(List<Transaction> transactions, int count, bool ascending) {
  List<Transaction> sortedTransactions = sortTransactions(transactions, ascending);
  return sortedTransactions.take(count).map((t) => t.coinName).toList();
}

void main() {
  List<String> topCoinsWithHighestAverageProfit = getTopCoins(transactions, 3, true);
