package com.example;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.LambdaLogger;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.S3Event;
import com.amazonaws.services.lambda.runtime.events.S3Event.S3EventRecord;
import com.amazonaws.services.s3.AmazonS3Client;
import com.amazonaws.services.s3.model.GetObjectRequest;
import com.amazonaws.services.s3.model.ObjectMetadata;
import com.amazonaws.services.s3.model.PutObjectRequest;
import com.amazonaws.services.s3.model.S3Object;
import com.amazonaws.services.s3.model.S3ObjectInputStream;
import com.imageio.ImageIO;
import com.imageio.ImageReader;
import com.imageio.ImageWriter;
import com.imageio.metadata.IIOMetadata;
import com.imageio.metadata.IIOMetadataNode;

import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.EnumSet;

public class ResizeImage implements RequestHandler<S3Event, Void> {

    @Override
    public Void handleRequest(S3Event s3Event, Context context) {
        LambdaLogger logger = context.getLogger();

        for (S3EventRecord record : s3Event.getRecords()) {
            String bucketName = record.getBucket().getName();
            String key = record.getObject().getKey();

            if (bucketName.equals("original_images") && key.startsWith("image-")) {
                logger.log("Processing image: " + key);

                try {
                    AmazonS3Client s3Client = new AmazonS3Client();
                    S3Object object = s3Client.getObject(new GetObjectRequest(bucketName, key));

                    InputStream inputStream = object.getObjectContent();
                    BufferedImage image = ImageIO.read(inputStream);

                    int width = image.getWidth();
                    int height = image.getHeight();

                    // Resize the image to 500px wide
                    BufferedImage resizedImage = ImageIO.getImageReader(image).read(0);
                    resizedImage = resizedImage.getScaledInstance(500, -1, Image.SCALE_SMOOTH);

                    // Create a new output stream
                    ByteArrayOutputStream outputStream = new ByteArrayOutputStream();

                    // Write the resized image to the output stream
                    ImageIO.write(resizedImage, "jpg", outputStream);

                    // Create a new S3Object and upload the resized image
                    S3Object resizedObject = new S3Object();
                    resizedObject.setBucketName(bucketName);
                    resizedObject.setKey("resized_images/" + key);
                    resizedObject.setObjectContent(new ByteArrayInputStream(outputStream.toByteArray()));

                    s3Client.putObject(new PutObjectRequest(bucketName, resizedObject.getKey(), resizedObject.getObjectContent(), new ObjectMetadata()));

                    logger.log("Resized image uploaded successfully: " + resizedObject.getKey());
                } catch (IOException e) {
                    logger.log("Error processing image: " + e.getMessage());
                }
            }
        }

        return null;
    }
}
```

