  const [authorized, setAuthorized] = useState(false);

  useEffect(() => {
    const getDeviceId = async () => {
      const response = await axios.get('/api/auth', {
        params: { deviceId },
      });

      setDeviceId(response.data.deviceId);
      setAuthorized(response.data.authorized);
