package com.example.exceltocsv;

import org.apache.poi.ss.usermodel.Cell;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.ss.usermodel.Workbook;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

public class ExcelToCsvConverter {
    public static void main(String[] args) {
        String excelFile = "input.xlsx";
        String csvFile = "output.csv";

        try {
            Workbook workbook = new XSSFWorkbook(new File(excelFile));
            Sheet sheet = workbook.getSheetAt(0);
            List<List<String>> data = new ArrayList<>();

            for (Row row : sheet) {
                List<String> rowData = new ArrayList<>();
                for (Cell cell : row) {
                    rowData.add(cell.toString());
                }
                data.add(rowData);
            }

            writeCSV(data, csvFile);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static void writeCSV(List<List<String>> data, String csvFile) {
        try {
            File csvFileObject = new File(csvFile);
            csvFileObject.createNewFile();

            java.io.BufferedWriter writer = new java.io.BufferedWriter(new java.io.FileWriter(csvFileObject));
            for (List<String> rowData : data) {
                for (String cellData : rowData) {
                    writer.append(cellData).append(",");
                }
                writer.newLine();
            }
            writer.close();
        } catch (IOException e) {
