import org.apache.poi.xssf.usermodel.XSSFWorkbook;
import org.apache.poi.ss.usermodel.Sheet;
import org.apache.poi.ss.usermodel.Row;
import org.apache.poi.ss.usermodel.Cell;
import org.apache.poi.ss.usermodel.CellType;
import org.apache.poi.ss.usermodel.IndexedColors;
import com.opencsv.CSVWriter;
import com.opencsv.CSVWriterBuilder;

import java.io.FileInputStream;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.Writer;
import java.util.ArrayList;
import java.util.List;

public class ExcelToCsvConverter {

    public static void main(String[] args) {
        String excelFile = "path/to/your/excel/file.xlsx";
        String csvFile = "path/to/your/csv/file.csv";

        try (FileInputStream inputStream = new FileInputStream(excelFile);
             XSSFWorkbook workbook = new XSSFWorkbook(inputStream);
             Sheet sheet = workbook.getSheetAt(0);
             Row row;
             Cell cell;
             List<String[]> data = new ArrayList<>();
             CSVWriter writer = new CSVWriterBuilder(new FileOutputStream(csvFile)).build();

             for (int i = 1; i <= sheet.getLastRowNum(); i++) {
                 row = sheet.getRow(i);
                 data.add(new String[row.getLastCellNum()]);

                 for (int j = 0; j < row.getLastCellNum(); j++) {
                     cell = row.getCell(j);
                     data.get(i - 1)[j] = getCellValue(cell);
                 }
             }

             writer.writeAll(data);
             writer.close();

             System.out.println("Excel file converted to CSV file successfully.");

         } catch (IOException e) {
             e.printStackTrace();
         }
    }

    private static String getCellValue(Cell cell) {
        switch (cell.getCellType()) {
            case CellType.STRING:
                return cell.getStringCellValue();
            case CellType.NUMERIC:
                return String.valueOf(cell.getNumericCellValue());
            case CellType.BOOLEAN:
                return String.valueOf(cell.getBooleanCellValue());
            case CellType.FORMULA:
                return cell.getFormulaCellValue();
            default:
                return "";
        }
    }
}
