	typeName := fmt.Sprintf("%s.%s", packageName, structName)
	t := reflect.TypeOf(reflect.ValueOf(typeName))
	avroSchema := generateSchema(t)
	ioutil.WriteFile("struct.avsc", []byte(avroSchema), 0644)
}
func generateSchema(t reflect.Type) string {
	switch t.Kind() {
	case reflect.Struct:
		schema := fmt.Sprintf("{\"type\": \"record\", \"name\": \"%s\", \"fields\": [", t.Name())
		for i := 0; i < t.NumField(); i++ {
			field := t.Field(i)
			schema += fmt.Sprintf("{\"name\": \"%s\", \"type\": \"%s\"}", field.Name, generateSchema(field.Type))
			if i < t.NumField()-1 {
				schema += ", "
			}
		}
		schema += "]}"
		return schema
	case reflect.Array, reflect.Slice:
		elemType := t.Elem()
		schema := fmt.Sprintf("{\"type\": \"array\", \"items\": %s}", generateSchema(elemType))
		return schema
	case reflect.Map:
		keyType := t.Key()
		valueType := t.Elem()
		schema := fmt.Sprintf("{\"type\": \"map\", \"values\": %s, \"key\": %s}", generateSchema(valueType), generateSchema(keyType))
		return schema
	default:
		return fmt.Sprintf("{\"type\": \"%s\"}", t.Kind())
	}
}

