Next, create a middleware class to extract the username from the JWT token:

```csharp
public class UsernameMiddleware
{
    private readonly RequestDelegate _next;
    private readonly IConfiguration _configuration;

    public UsernameMiddleware(RequestDelegate next, IConfiguration configuration)
    {
        _next = next;
        _configuration = configuration;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Get the JWT token from the authorization header
        string token = context.Request.Headers["Authorization"].FirstOrDefault()?.Split(" ")[1];

        // If the token is null, skip the middleware
        if (string.IsNullOrEmpty(token))
        {
            await _next(context);
            return;
        }

        // Verify the token
        TokenValidationParameters parameters = new TokenValidationParameters
        {
            IssuerSigningKey = Encoding.ASCII.Parse(_configuration["Jwt:Key"]),
            ValidateIssuer = true,
            ValidateAudience = true,
            ValidateLifetime = true,
            ValidateIssuerSigningKey = true
        };

        JwtSecurityToken tokenHandler = new JwtSecurityTokenHandler();
        ClaimsPrincipal principal = tokenHandler.ValidateToken(token, parameters, out SecurityToken validToken);

        // Get the username from the claims
        string username = principal.Claims.FirstOrDefault(c => c.Type == "username")?.Value;

        // Set the username in the context
        context.Items["Username"] = username;

        // Continue with the next middleware
        await _next(context);
    }
}
```

