    const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
    const scrollBottom = window.innerHeight || document.documentElement.clientHeight;
    const scrollHeight = document.body.scrollHeight;

    if (scrollTop + scrollBottom >= scrollHeight) {
      handleResize();
    }
  };

